def transform(grid):
    """Fill hollow square frames: odd side length with 7, even side length with 2."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            border = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                      if y in (r0, r1) or x in (c0, c1)}
            if r1 - r0 >= 2 and c1 - c0 >= 2 and set(cells) == border:
                fill = 7 if (r1 - r0 + 1) % 2 else 2
                for y in range(r0 + 1, r1):
                    for x in range(c0 + 1, c1):
                        out[y][x] = fill
    return out

